INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW22YJNIH', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Computational linguist Yael Petrov analyzed a corpus of over 4,700 nineteenth-century Yiddish newspaper editorials from Vilnius and discovered that writers who employed code-switching between Yiddish and Russian were published at nearly twice the rate of monolingual contributors ______ Petrov proposed that bilingual editorials attracted a broader readership, which in turn made editors more receptive to multilingual submissions.', $lyceon_json$[{"key":"A","text":"contributors, Petrov"},{"key":"B","text":"contributors; accordingly, Petrov"},{"key":"C","text":"contributors; nevertheless, Petrov"},{"key":"D","text":"contributors Petrov"}]$lyceon_json$::jsonb, 'B', NULL, E'The second clause offers an explanation that follows logically from the finding in the first clause, so a semicolon paired with the conjunctive adverb "accordingly" correctly joins the two independent clauses and signals the cause-and-effect relationship. The option using only a comma creates a comma splice between two independent clauses. The option using "nevertheless" pairs a grammatically correct semicolon with a conjunctive adverb that signals contrast, which contradicts the logical relationship: the second clause explains the first rather than opposing it. The option with no punctuation at all produces a run-on sentence.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW22YWE5A', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Which choice most logically completes the text?', E'Archaeologists excavating a Bronze Age settlement along the upper Tigris River discovered seventeen clay tablets inscribed with an unknown script. The symbols share no recognizable features with contemporaneous cuneiform systems used by nearby Mesopotamian polities. Chemical analysis of the clay, however, confirmed that the tablets were produced from local alluvial deposits rather than imported. The settlement shows no architectural evidence of sustained contact with distant civilizations—no foreign pottery styles, no non-local building materials, no imported metalwork. Taken together, these findings suggest that ________', $lyceon_json$[{"key":"A","text":"the script was likely developed independently by the settlement's inhabitants rather than borrowed from an outside writing tradition."},{"key":"B","text":"the inhabitants were unable to communicate with neighboring Mesopotamian communities."},{"key":"C","text":"cuneiform writing systems originated in multiple geographic locations simultaneously."},{"key":"D","text":"the tablets served a decorative rather than communicative function."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage establishes three converging pieces of evidence: the script shares no features with contemporaneous cuneiform, the clay is local, and the settlement shows no signs of contact with distant civilizations. Together these most logically support the inference that the writing system was developed independently by the local population. The claim about inability to communicate with neighbors overstates the evidence; lacking a shared script does not preclude oral communication or other forms of contact. The claim about cuneiform originating in multiple locations extrapolates far beyond the passage, which discusses one settlement''s script and does not address cuneiform''s origins. The claim about a decorative function is unsupported; the passage provides no information about the tablets'' purpose, and the term script implies communicative intent.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW24E2A1X', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'Which choice completes the text with the most logical transition?', E'Marine biologists at the Coral Reef Monitoring Station in Palau have documented a 37 percent increase in staghorn coral coverage across the surveyed reef since 2019. _______ their findings suggest that the reef restoration techniques piloted in the region are producing measurable results.', $lyceon_json$[{"key":"A","text":"Taken together,"},{"key":"B","text":"By contrast,"},{"key":"C","text":"On the other hand,"},{"key":"D","text":"Nevertheless,"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct choice is "Taken together," because the second sentence draws a conclusion from the data presented in the first sentence. The relationship is one of summarizing evidence to reach a broader point. "By contrast" and "On the other hand" incorrectly signal a contrast or opposition between the two sentences, when in fact the second sentence follows logically from the first. "Nevertheless" implies the conclusion was reached despite some obstacle, but no obstacle is presented in the passage.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW25ANO18', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 2, 'mcq', E'While writing a report for an environmental science class, a student wants to emphasize the surprising durability of tardigrades under extreme conditions. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'• Tardigrades, also known as water bears, are microscopic invertebrates typically measuring 0.1 to 1.5 millimeters in length.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW28CX5TA', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best states the main idea of the text?', E'Coral reefs occupy less than one percent of the ocean floor, yet they support roughly twenty-seven percent of all known marine fish species. This remarkable concentration of biodiversity arises because reefs provide an intricate three-dimensional habitat: crevices shelter small invertebrates, branching structures offer perches for filter feeders, and sunlit surfaces host photosynthetic algae that form the base of a dense food web. Where surrounding open waters may be nutrient-poor, the reef itself functions as an oasis of biological productivity.', $lyceon_json$[{"key":"A","text":"Coral reefs support a disproportionately large share of marine biodiversity because of the complex habitat they provide."},{"key":"B","text":"Marine fish populations have declined in open waters, causing species to migrate toward coral reef environments."},{"key":"C","text":"Photosynthetic algae are the most important organisms living on coral reefs."},{"key":"D","text":"Scientists have recently discovered that coral reefs cover a smaller area of the ocean floor than previously estimated."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage states that coral reefs occupy less than one percent of the ocean floor yet support about twenty-seven percent of marine fish species, and it explains that this biodiversity concentration results from the intricate three-dimensional habitat reefs provide. The choice about disproportionate biodiversity supported by complex habitat captures this central idea. The choice about fish migrating from open waters introduces a claim about decline and migration never made in the passage. The choice about photosynthetic algae elevates one supporting detail into a main idea, misrepresenting the passage''s emphasis. The choice about a recent discovery of reef area mischaracterizes the passage, which presents the statistic as established fact, not a new finding.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ADCMAQ', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 3, 'mcq', E'Based on the texts, how would the author of Text 1 most likely characterize the approach described in Text 2?', E'Text 1:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2B37CVZ', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the overall structure of the text?', E'When architect Yusuf al-Rashid designed the Karachi Central Library in 1967, he incorporated latticed concrete screens — known as jali — that filtered harsh sunlight while promoting natural ventilation. Critics initially dismissed these elements as ornamental nostalgia for Mughal aesthetics. Subsequent thermal studies, however, demonstrated that the jali screens reduced interior temperatures by an average of 9 degrees Celsius compared to glass-walled buildings of similar size, vindicating al-Rashid''s integration of vernacular techniques into modernist design.', $lyceon_json$[{"key":"A","text":"It presents a design decision, describes an initial reaction to it, and then provides evidence that counters that reaction."},{"key":"B","text":"It compares two architectural traditions and argues that one is superior to the other."},{"key":"C","text":"It traces the chronological development of a building technique from ancient to modern times."},{"key":"D","text":"It describes a problem with modern architecture and proposes a new solution."}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is the choice describing a design decision, an initial reaction, and countering evidence. The passage first introduces al-Rashid''s use of jali screens, then notes critics dismissed them as ornamental nostalgia, and finally presents thermal studies that vindicated the design. The choice about comparing two traditions and declaring one superior misrepresents the structure: the passage does not set up a comparison between two rival approaches but rather shows how one specific design was initially criticized and later validated. The choice about tracing chronological development is inaccurate because the passage focuses on one building from 1967 and its reception, not an evolution of technique across eras. The choice about proposing a new solution is wrong because the passage describes a design already implemented, not a response to an identified problem.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2BETP2D', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 2, 'mcq', E'Which choice best describes the relationship between the two texts?', E'Text 1:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2F6IU6V', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The novelist Elara Voss insisted that the publisher ______ the original manuscript''s unconventional punctuation in all future editions, arguing that the irregular commas and semicolons were integral to the work''s rhythmic structure.', $lyceon_json$[{"key":"A","text":"preserved"},{"key":"B","text":"preserves"},{"key":"C","text":"preserve"},{"key":"D","text":"had preserved"}]$lyceon_json$::jsonb, 'C', NULL, E'The verb "insisted" followed by "that" introduces a mandative subjunctive clause. In formal English, the subjunctive requires the base form of the verb regardless of the subject''s person or number, so "preserve" is correct. The option "preserved" uses the past indicative, which is inappropriate for a subjunctive clause expressing a demand. The option "preserves" uses the present indicative third-person singular form, which does not conform to the subjunctive mood required after verbs of demand such as "insisted." The option "had preserved" uses the past perfect indicative, which incorrectly shifts the action to a time before the insisting and changes the meaning from a demand to a description of a completed action.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2G3HPD3', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the function of the second sentence in the text?', E'The fruit of the baobab tree contains six times more vitamin C than an orange and twice the calcium of milk. For centuries, communities across the Sahel region have ground the dried pulp into a powder used in porridges, beverages, and medicinal preparations. Today, international food companies are marketing baobab powder as a premium "superfood," raising concerns among local farmers about equitable access to global supply chains.', $lyceon_json$[{"key":"A","text":"to provide historical context for a traditional practice"},{"key":"B","text":"to challenge a widely held nutritional claim"},{"key":"C","text":"to explain why international companies became interested in baobab"},{"key":"D","text":"to compare baobab cultivation methods across different regions"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is the choice stating that the sentence provides historical context for a traditional practice. The second sentence describes how communities have used baobab pulp "for centuries," establishing the long history of local use before the passage shifts to modern commercial interest. The choice about challenging a nutritional claim is incorrect because the second sentence does not dispute the nutritional data presented in the first sentence. The choice about explaining corporate interest misreads the purpose: the second sentence describes traditional use, while corporate interest is introduced in the third sentence. The choice about comparing cultivation methods is wrong because the sentence discusses preparation and consumption, not farming techniques.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2HUC55L', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'What can most reasonably be inferred from the text about the relationship between sleep duration and athletic performance?', E'A 2019 study at a Division II university tracked the sleep habits of forty-three varsity swimmers over an eight-week training block. Swimmers who consistently logged fewer than six hours of sleep per night showed measurable declines in reaction time and stroke efficiency by the fourth week, while those sleeping seven to nine hours maintained or improved their metrics throughout the study period. The researchers noted that no swimmer who averaged under six hours voluntarily chose that schedule; all cited academic deadlines or part-time employment as the cause.', $lyceon_json$[{"key":"A","text":"Consistently sleeping fewer than six hours per night may impair swimmers' reaction time and stroke efficiency over several weeks."},{"key":"B","text":"Swimmers who sleep more than nine hours per night will achieve the greatest performance gains."},{"key":"C","text":"Academic deadlines are the single most significant barrier to athletic performance at Division II universities."},{"key":"D","text":"Reaction time is a more important performance metric than stroke efficiency for competitive swimmers."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage states that swimmers sleeping fewer than six hours showed declines in reaction time and stroke efficiency by the fourth week, while those sleeping seven to nine hours maintained or improved. It is reasonable to infer that consistently insufficient sleep may impair these performance metrics. The claim about sleeping more than nine hours producing the greatest gains goes beyond the data, which only compared under-six-hour sleepers to seven-to-nine-hour sleepers. The claim about academic deadlines being the single most significant barrier overstates the passage, which mentions deadlines and part-time employment as causes of short sleep but makes no ranking of barriers to performance. The claim about reaction time being more important than stroke efficiency introduces a comparison the passage never makes; both are simply reported as affected metrics.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2HW1EJE', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'A literary scholar argues that the narrator''s description of the market scene functions primarily to reveal Lien''s internal conflict rather than to document the setting''s physical details. Which quotation from the novel would most effectively support this interpretation?', E'In Phan Huyen''s novel The Saffron Ledger, the protagonist Lien accompanies her grandmother to an open-air market in a coastal Vietnamese town during the monsoon season of 1963. The scene has drawn critical attention because of its dense sensory imagery—references to fermented shrimp paste, rain-soaked tarpaulins, and vendors shouting over the downpour. Some scholars read the passage as ethnographic documentation of mid-century market culture, while others contend that the descriptive choices are calibrated to externalize Lien''s psychological state as she contemplates leaving her family to study pharmacy in Saigon.', $lyceon_json$[{"key":"A","text":"\"The pyramids of dragon fruit stood impossibly still against the chaos, and Lien wondered whether anything rooted so firmly could understand the compulsion to be uprooted.\""},{"key":"B","text":"\"Grandmother counted out eleven piasters for a kilo of mackerel, folding each note with the mechanical precision Lien had observed every Tuesday since childhood.\""},{"key":"C","text":"\"By seven o'clock the fishmongers had arranged their stalls in the customary east-to-west row, the ice already softening under the morning humidity.\""},{"key":"D","text":"\"The market operated under a permit system introduced by the provincial authority in 1958, requiring each vendor to display a laminated identification card.\""}]$lyceon_json$::jsonb, 'A', NULL, E'The scholar''s claim is that the market description reveals Lien''s internal conflict about leaving her family. The quotation about dragon fruit standing still while Lien wonders whether anything rooted could understand the compulsion to be uprooted directly projects her psychological tension—between rootedness and departure—onto a market object, supporting the scholar''s interpretation. The quotation about the grandmother counting piasters depicts a habitual action and could suggest Lien''s familiarity with routine, but it does not explicitly externalize her conflict about leaving. The quotation about fishmongers arranging stalls offers purely physical setting details with no psychological dimension. The quotation about the permit system provides administrative context entirely disconnected from Lien''s inner life.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2IUIKZU', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The collection of rare lichen specimens that the university''s bryology department acquired during a 2019 expedition to the Faroe Islands ______ currently on display in the Lúðvík Kristjánsson Natural History Building.', $lyceon_json$[{"key":"A","text":"are"},{"key":"B","text":"is"},{"key":"C","text":"were"},{"key":"D","text":"have been"}]$lyceon_json$::jsonb, 'B', NULL, E'The subject of the sentence is "collection," a singular noun. Although the intervening prepositional phrase "of rare lichen specimens" contains a plural noun, the verb must agree with the actual subject. The singular present-tense verb "is" correctly agrees with "collection" and matches the time signal "currently." The option "are" is plural and does not agree with the singular subject. The option "were" is both plural and past tense, conflicting with both the subject''s number and the present-time context. The option "have been" uses the plural auxiliary "have," which fails to agree with the singular subject.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2JVC5EF', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Political theorist Adaora Nnaji has argued that postcolonial democratic institutions often replicate the centralized administrative structures of their colonial predecessors, limiting genuine local governance. Her critics counter that such institutions, despite their origins, develop independently responsive mechanisms over successive election cycles. _______ Nnaji''s most recent longitudinal study of 14 West African municipalities found that budgetary autonomy at the local level declined even as the number of elections increased, suggesting that procedural democracy alone does not dismantle inherited power hierarchies.', $lyceon_json$[{"key":"A","text":"In addition,"},{"key":"B","text":"To illustrate,"},{"key":"C","text":"On this point,"},{"key":"D","text":"In any case,"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct choice is "On this point," because the third sentence directly addresses the disagreement described in the first two sentences by presenting Nnaji''s empirical evidence. The transition signals that what follows engages with the specific debate already introduced. "In addition" would suggest the third sentence merely adds a new, separate point rather than responding to the critics'' counterargument. "To illustrate" implies the third sentence is an example of the critics'' claim, but Nnaji''s study actually undermines their position. "In any case" signals dismissal of the preceding debate, whereas the study is presented as directly relevant to resolving it.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2KGPDPX', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The implications of the geophysicist''s discovery—that subsurface magma channels beneath the caldera, not the volcanic cone itself, ______ the observed pattern of seismic tremors—were debated at the international volcanology conference last September.', $lyceon_json$[{"key":"A","text":"generates"},{"key":"B","text":"generating"},{"key":"C","text":"generate"},{"key":"D","text":"has generated"}]$lyceon_json$::jsonb, 'C', NULL, E'The embedded clause introduced by "that" requires a finite verb whose subject is "subsurface magma channels," a plural noun. The parenthetical phrase "not the volcanic cone itself" is set off by commas and does not change the subject. The plural verb "generate" correctly agrees with "channels." The option "generates" is a singular verb that would incorrectly agree with "cone" rather than the actual subject. The option "generating" is a participle, not a finite verb, and would leave the embedded clause without a main verb, creating a sentence fragment within the dash-delimited aside. The option "has generated" uses the singular auxiliary "has," which does not agree with the plural subject "channels."', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2KTAEM8', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'While studying the migration patterns of Arctic terns along the Norwegian coastline, ornithologist Dagny Elstad documented an unusual stopover behavior at the Vesterålen archipelago. The terns consistently paused at the same rocky outcrop for exactly two days before resuming their southward journey ______ Elstad''s observations suggested that the outcrop''s tidal pools provided a uniquely nutrient-dense feeding opportunity unavailable at other coastal sites.', $lyceon_json$[{"key":"A","text":"journey, and Elstad's"},{"key":"B","text":"journey, Elstad's"},{"key":"C","text":"journey Elstad's"},{"key":"D","text":"journey and, Elstad's"}]$lyceon_json$::jsonb, 'A', NULL, E'Two independent clauses—one ending with "journey" and another beginning with "Elstad''s observations"—must be joined properly. A comma followed by the coordinating conjunction "and" correctly links the clauses. The option using only a comma creates a comma splice, which is incorrect. The option with no punctuation at all produces a run-on sentence. The option that places a comma after "and" rather than before it misplaces the required punctuation, separating the conjunction from the clause it introduces.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2N91AG0', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'What can most reasonably be inferred from the text about Hollowell''s view of algorithmic hiring tools?', E'Labor economist Teresa Hollowell has noted that algorithmic hiring tools trained on historical employment data may systematically disadvantage candidates from demographic groups that were underrepresented in the training period. She points out that if an algorithm learns that successful past hires disproportionately held credentials from a small set of elite institutions, it will assign lower scores to equally qualified applicants whose credentials come from other schools—not because those credentials are inferior, but because the training data reflects prior selection biases rather than actual job performance. Hollowell concedes that algorithmic tools can process applications at a scale no human review panel could match, yet she cautions that efficiency gains are illusory if they merely accelerate the reproduction of existing inequities.', $lyceon_json$[{"key":"A","text":"Hollowell believes that the speed advantage of algorithmic tools does not justify their use if those tools perpetuate historical hiring biases."},{"key":"B","text":"Hollowell advocates banning all algorithmic hiring tools until their training datasets can be certified as free of demographic bias."},{"key":"C","text":"Hollowell considers credential quality from elite institutions to be a reliable predictor of job performance."},{"key":"D","text":"Hollowell argues that human review panels are inherently less biased than algorithmic systems in evaluating candidates."}]$lyceon_json$::jsonb, 'A', NULL, E'Hollowell concedes that algorithmic tools offer unmatched processing scale but calls efficiency gains illusory if they accelerate existing inequities. This implies she believes the speed advantage does not justify use when historical biases are reproduced—a conclusion that follows logically from her stated position without overreaching. The claim about advocating a ban goes beyond her stated caution; she identifies a problem but the passage does not attribute a prohibition stance to her. The claim about elite credentials being reliable predictors directly contradicts her argument that the algorithm''s preference for elite credentials reflects prior selection biases rather than actual job performance. The claim about human panels being inherently less biased is unsupported; Hollowell acknowledges the scale limitation of human review but makes no comparative claim about bias levels.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ND32E1', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 1, 'mcq', E'While writing a summary for a general audience, a student wants to explain what miombo woodlands are and where they occur. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'• Miombo woodlands are a type of tropical and subtropical grassland-forest mosaic.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2NNTWU1', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 3, 'mcq', E'While writing an article for a history journal, a student wants to challenge the common characterization of Eli Whitney''s cotton gin as a labor-saving invention by highlighting its unintended social consequences. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'• Eli Whitney patented the cotton gin in 1794, a device that mechanically separated cotton fibers from seeds.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2NX4G3J', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'A botanist claims that Venus flytraps rely on mechanical stimulation rather than chemical detection to trigger their trapping mechanism. Which quotation from a research article, if true, would most directly support this claim?', E'The Venus flytrap (Dionaea muscipula) captures insects using a pair of hinged leaf lobes that snap shut when trigger hairs on their inner surface are deflected. Each lobe contains three to four of these slender sensory hairs. Researchers have long debated whether the trap responds to physical contact alone or also detects chemical signals from prey. Recent experiments have used glass beads, nylon filaments, and drops of distilled water to probe the mechanism, finding that certain non-biological stimuli can reliably activate the trap under controlled conditions.', $lyceon_json$[{"key":"A","text":"\"When researchers placed dead crickets on the lobes without deflecting the trigger hairs, no closure occurred in any of the 38 trials.\""},{"key":"B","text":"\"Chemical analysis of the mucilage coating the lobe surface revealed trace concentrations of digestive enzymes even before prey capture.\""},{"key":"C","text":"\"Venus flytraps growing in nitrogen-poor bogs obtained up to 75 percent of their nitrogen from captured insects.\""},{"key":"D","text":"\"Genetic sequencing showed that Venus flytraps share a common ancestor with several non-carnivorous sundew relatives.\""}]$lyceon_json$::jsonb, 'A', NULL, E'The botanist''s claim is that mechanical stimulation, not chemical detection, triggers the trap. The finding that dead crickets placed without deflecting trigger hairs produced no closure directly supports this by showing that even the chemical presence of prey is insufficient without physical contact. The finding about digestive enzymes relates to the digestive process rather than the triggering mechanism. The finding about nitrogen acquisition addresses the nutritional benefit of carnivory, not the mechanism of trap activation. The finding about genetic ancestry concerns evolutionary relationships and has no bearing on how the trap is triggered.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2OMJTLI', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Archaeobotanist Priya Deshpande examined carbonized grain fragments recovered from a storage pit at Mohenjo-daro—fragments so degraded that earlier researchers had dismissed them as contaminants ______ her spectroscopic analysis revealed traces of emmer wheat, a crop not previously associated with Indus Valley agriculture.', $lyceon_json$[{"key":"A","text":"contaminants, her"},{"key":"B","text":"contaminants her"},{"key":"C","text":"contaminants, so her"},{"key":"D","text":"contaminants, but her"}]$lyceon_json$::jsonb, 'D', NULL, E'The clause before the blank describes earlier researchers dismissing the fragments, while the clause after the blank presents Deshpande''s contrasting discovery. A comma followed by the coordinating conjunction "but" correctly joins the two independent clauses and signals the adversative relationship between the dismissal and the positive finding. The option using only a comma creates a comma splice between two independent clauses. The option with no punctuation produces a run-on sentence. The option using "so" is a coordinating conjunction that signals consequence or result, implying the dismissal caused the spectroscopic finding—a nonsensical causal relationship, since the discovery contradicts rather than follows from the earlier dismissal.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2PBGQTX', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the function of the reference to "peat deposits" in the text?', E'Paleoecologist Miriam Thatcher has argued that the high-altitude meadows of the Cantabrian Mountains were not, as long assumed, natural features of the post-glacial landscape but rather the product of sustained pastoral burning by Mesolithic herding communities. Thatcher points to peat deposits from roughly 8,200 years ago that contain sharply elevated charcoal concentrations coinciding with a sudden decline in arboreal pollen — a pattern inconsistent with lightning-caused fires, which leave more diffuse charcoal signatures. Her critics counter that volcanic activity in the region could produce similar pollen disruptions, though Thatcher notes that the relevant strata lack the tephra layers that invariably accompany volcanic events.', $lyceon_json$[{"key":"A","text":"to serve as physical evidence supporting a claim that challenges a prevailing assumption"},{"key":"B","text":"to introduce a counterargument to the theory that meadows resulted from human activity"},{"key":"C","text":"to illustrate the difficulty of distinguishing between natural and human-caused fires"},{"key":"D","text":"to demonstrate that Mesolithic communities relied primarily on agriculture rather than herding"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is the choice stating the peat deposits serve as physical evidence supporting a claim that challenges a prevailing assumption. Thatcher argues against the assumption that the meadows are natural post-glacial features, and she cites peat deposits with elevated charcoal and declining arboreal pollen as evidence that human burning created the meadows. The choice about introducing a counterargument reverses the rhetorical role: the peat deposits support Thatcher''s theory rather than opposing it; the counterargument comes later from critics who cite volcanic activity. The choice about illustrating the difficulty of distinguishing fire types captures only a partial aspect of the evidence — the passage does mention different charcoal signatures, but the peat deposits are introduced to support Thatcher''s specific claim, not to highlight ambiguity. The choice about agriculture misreads the passage, which explicitly describes herding communities, not agricultural ones.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2Q7EJ7O', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'An urban planner argues that converting underused parking lots into green spaces would reduce citywide surface temperatures more effectively than installing reflective roofing materials. Which finding, if true, would most directly support the planner''s argument?', E'Cities experience elevated temperatures compared with surrounding rural areas, a phenomenon known as the urban heat island effect. Paved surfaces absorb solar radiation during the day and re-emit it as heat at night, sustaining high temperatures around the clock. Two leading mitigation strategies have emerged: replacing dark pavement with vegetation, and coating rooftops with reflective materials that bounce incoming sunlight back into the atmosphere. While both approaches reduce heat absorption, they operate through different physical mechanisms—evapotranspiration versus albedo modification—and their relative effectiveness remains debated among researchers.', $lyceon_json$[{"key":"A","text":"In a three-year trial across fourteen neighborhoods, areas where parking lots were replaced by tree canopy recorded average summer surface temperatures 4.7 degrees Celsius lower than baseline, whereas neighborhoods with reflective roofs recorded reductions of only 1.9 degrees Celsius."},{"key":"B","text":"A nationwide survey found that 68 percent of residents preferred green spaces to reflective rooftops for aesthetic reasons."},{"key":"C","text":"Reflective roofing materials have decreased in cost by 23 percent over the past decade, making them more accessible to building owners."},{"key":"D","text":"Urban green spaces have been associated with improved mental health outcomes in several longitudinal studies conducted in European cities."}]$lyceon_json$::jsonb, 'A', NULL, E'The planner''s argument is specifically that converting parking lots to green spaces reduces surface temperatures more effectively than reflective roofing. The trial data showing a 4.7 degrees Celsius reduction from green-space conversion versus only 1.9 degrees Celsius from reflective roofs provides a direct quantitative comparison supporting this claim. The survey about resident aesthetic preferences addresses public opinion, not temperature reduction effectiveness. The cost decrease of reflective materials relates to economic accessibility, not comparative cooling performance. The mental health studies concern a different benefit of green spaces entirely and do not address temperature mitigation.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2RJYBB5', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'Which choice completes the text with the most logical transition?', E'The 1927 Solvay Conference is often credited with crystallizing the Copenhagen interpretation of quantum mechanics as the dominant framework. _______ several attendees, including Albert Einstein and Erwin Schrödinger, left the conference unconvinced and spent the following decades developing alternative formulations that challenged the Copenhagen view.', $lyceon_json$[{"key":"A","text":"In other words,"},{"key":"B","text":"For instance,"},{"key":"C","text":"However,"},{"key":"D","text":"Similarly,"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct choice is "However," because the second sentence introduces a counterpoint to the first: although the conference supposedly solidified the Copenhagen interpretation, several notable attendees actually rejected it. "In other words" incorrectly signals a restatement, but the second sentence adds new, contrasting information rather than rephrasing the first. "For instance" would introduce an example illustrating the first sentence, but the second sentence contradicts it. "Similarly" implies agreement or parallel, which is the opposite of the contrast being drawn.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2TJIQZC', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Although the conservation team had restored the sixteenth-century altarpiece with painstaking care, the lead curator insisted that neither the newly applied varnish nor the reinforced oak backing ______ sufficient to protect the work from the humidity fluctuations common in the chapel''s nave.', $lyceon_json$[{"key":"A","text":"were"},{"key":"B","text":"was"},{"key":"C","text":"are"},{"key":"D","text":"have been"}]$lyceon_json$::jsonb, 'B', NULL, E'In a "neither...nor" construction, the verb agrees with the nearer subject. Here, "the reinforced oak backing" is singular and closest to the verb, so the singular past-tense "was" is correct. The past tense is also required to maintain consistency with the past-tense framing established by "insisted." The option "were" uses a plural verb that does not agree with the nearer singular subject. The option "are" is plural and shifts to present tense, breaking both agreement and tense consistency. The option "have been" uses the plural auxiliary "have" and shifts to present perfect tense, failing on both counts.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2VUIVKZ', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'As used in the text, what does the word "temper" most nearly mean?', E'In a 2019 policy brief, economist Adaeze Okafor argued that while deregulation can stimulate short-term economic growth, governments must temper such measures with robust consumer protections. Without these safeguards, she warned, rapid market expansion tends to concentrate wealth among established firms while eroding the purchasing power of lower-income households.', $lyceon_json$[{"key":"A","text":"moderate"},{"key":"B","text":"anneal"},{"key":"C","text":"provoke"},{"key":"D","text":"publicize"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is "moderate." Okafor argues that deregulation should be accompanied by consumer protections, meaning governments must restrain or moderate the intensity of such measures. "Anneal" refers to heating and slowly cooling metal to toughen it, a metallurgical process unrelated to adjusting policy intensity. "Provoke" means to incite or stimulate a reaction, which is the opposite of the restraining action the passage describes. "Publicize" means to make widely known, but the passage is about balancing policy measures, not about communicating them.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2VVTEXC', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 3, 'mcq', E'Which choice best describes the main idea of the text?', E'Philosopher Kwame Gyekye challenged the widespread characterization of African ethical systems as strictly communitarian by arguing that individual moral responsibility is equally fundamental in Akan thought. Gyekye acknowledged that communal bonds shape identity: a person''s obligations to kin, clan, and polity are not optional extras but constitutive features of selfhood. Yet he insisted that Akan proverbs and judicial customs also presuppose an autonomous agent capable of deliberation and deserving of praise or blame. Without this individual dimension, Gyekye contended, communal ethics would collapse into determinism, stripping moral evaluation of its coherence. His position, which he termed moderate communitarianism, thus rejects both radical individualism and the pure communalism attributed to African philosophy by earlier scholars.', $lyceon_json$[{"key":"A","text":"Gyekye argued that Akan ethics integrates individual moral agency with communal obligations, challenging the view that African philosophy is purely communitarian."},{"key":"B","text":"Gyekye demonstrated that Akan proverbs are more philosophically rigorous than Western ethical frameworks."},{"key":"C","text":"Gyekye rejected communal values in favor of an individualist ethic grounded in Akan judicial customs."},{"key":"D","text":"Gyekye proposed that moral evaluation is incoherent in any ethical system that acknowledges communal obligations."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage presents Gyekye''s argument that Akan thought encompasses both communal bonds and individual moral agency, and that earlier scholars wrongly described African ethics as purely communitarian. His position of moderate communitarianism rejects both extremes. The choice stating Gyekye integrated individual agency with communal obligations captures this nuanced central idea. The choice about Akan proverbs being more rigorous than Western frameworks introduces a comparative claim the passage never makes. The choice about Gyekye rejecting communal values misrepresents his position; he explicitly acknowledged that communal bonds are constitutive of selfhood. The choice about moral evaluation being incoherent with communal obligations inverts his argument—he said moral evaluation collapses without the individual dimension, not that communal obligations undermine it.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2XNWY46', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Archaeologist Miriam Kovač''s 2021 excavation of a Bronze Age settlement near Lake Ohrid uncovered ceramic vessels bearing decorative motifs previously associated exclusively with Aegean trading cultures. _______ the presence of local clay compositions in the vessels indicates that the designs were adopted by indigenous artisans rather than imported through direct trade.', $lyceon_json$[{"key":"A","text":"Moreover,"},{"key":"B","text":"Specifically,"},{"key":"C","text":"Consequently,"},{"key":"D","text":"Crucially, though,"}]$lyceon_json$::jsonb, 'D', NULL, E'The correct choice is "Crucially, though," because the second sentence qualifies the initial finding by introducing an important complication: the vessels bear Aegean motifs, but their local clay compositions reveal they were not imports. This relationship requires a transition that both signals importance and introduces a contrast. "Moreover" would simply add information in the same direction, missing the shift from apparent trade evidence to local production. "Specifically" would indicate the second sentence elaborates on the first, but instead it reframes its implications. "Consequently" implies a causal result, yet the second sentence does not follow as a logical effect of finding Aegean-style motifs—it complicates that finding.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2YYW1CW', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'According to the text, what is the primary reason Kondapalli craft traditions persisted for centuries despite political upheaval in the region?', E'In the Deccan plateau village of Kondapalli, artisans have produced lacquered wooden toys for at least four hundred years. Historians note that the craft survived successive changes in political authority—from the Reddi dynasty through the Qutb Shahi sultanate and into British colonial administration—because the toys served ritual functions that every ruling power tolerated. Festival effigies, votive figurines, and ceremonial gift sets maintained steady demand regardless of which court collected taxes. Moreover, the raw material—softwood from the Poniki tree—grew abundantly on nearby hillsides, insulating production from trade-route disruptions that crippled other regional crafts.', $lyceon_json$[{"key":"A","text":"The toys fulfilled ritual purposes that each successive ruling authority permitted to continue."},{"key":"B","text":"Artisans secretly practiced their craft in rural workshops hidden from colonial inspectors."},{"key":"C","text":"Foreign merchants exported the toys to distant markets, ensuring the craft's economic viability."},{"key":"D","text":"Kondapalli artisans adapted their designs to reflect the aesthetic preferences of each new ruling power."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage explicitly states that the craft survived because the toys served ritual functions that every ruling power tolerated, and that festival effigies, votive figurines, and ceremonial gift sets maintained steady demand. The choice about ritual purposes directly reflects this stated reason. The choice about secret workshops introduces a narrative of concealment absent from the passage. The choice about foreign merchants and export invents an economic mechanism not mentioned anywhere in the text. The choice about adapting designs to rulers'' preferences is an unsupported inference; the passage says the toys persisted because of their ritual role, not because artisans changed their style.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
